import{_ as a,o as t,c as s,ag as n}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Doc Creation Standard","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/reference/DocCreationStandard.md","filePath":"todo/study_plan/reference/DocCreationStandard.md"}'),o={name:"todo/study_plan/reference/DocCreationStandard.md"};function i(r,e,l,c,d,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="doc-creation-standard" tabindex="-1">Doc Creation Standard <a class="header-anchor" href="#doc-creation-standard" aria-label="Permalink to &quot;Doc Creation Standard&quot;">​</a></h1><p>The bar for writing any new study-plan doc — both the top-level <code>parts/Part_NN_*.md</code> files and the content docs they link to (anything in <code>java/</code>, <code>spring/</code>, etc. referenced from a Part row&#39;s Resources column).</p><p>Apply this BEFORE writing, not after. If a draft fails this standard, cut rather than rewrite.</p><hr><h2 id="the-single-test" tabindex="-1">The single test <a class="header-anchor" href="#the-single-test" aria-label="Permalink to &quot;The single test&quot;">​</a></h2><p>Every section, paragraph, and example must pass this:</p><blockquote><p>&quot;Would a senior Java backend interviewer actually ask about this, or would knowing it help answer a question they would ask?&quot;</p></blockquote><p>If no — don&#39;t write it. No exceptions. Length is never a virtue; depth in the right places is.</p><hr><h2 id="reader-profile" tabindex="-1">Reader profile <a class="header-anchor" href="#reader-profile" aria-label="Permalink to &quot;Reader profile&quot;">​</a></h2><p>The reader is an SDE2 who writes Java/Spring Boot daily, preparing for a senior Java backend interview. They:</p><ul><li>Already know how to use most Java/Spring APIs day-to-day. Skip basic-usage walkthroughs for topics they cold-know (e.g., basic HashMap usage, basic <code>@Transactional</code>, basic REST controllers). When unsure, default to skipping — the user will explicitly ask for a basic walkthrough if they need one for a less-familiar area (security/crypto, AWS, networking, etc.).</li><li>Need to know <strong>Java&#39;s specific choices deeply</strong> — bucket model, treeification, CAS, happens-before, propagation rules, proxy mechanics — not comparative surveys of how other languages do it.</li><li>Have limited brain context. Every line they have to read but then decide to skip costs more than it gives.</li></ul><hr><h2 id="what-earns-its-place" tabindex="-1">What earns its place <a class="header-anchor" href="#what-earns-its-place" aria-label="Permalink to &quot;What earns its place&quot;">​</a></h2><ul><li><strong>How Java&#39;s actual implementation works</strong> — internals, mechanisms, thresholds, the actual algorithm.</li><li><strong>Gotchas and pitfalls</strong> that bite in real Java code.</li><li><strong>Comparisons between Java&#39;s own types</strong> (HashMap vs LinkedHashMap vs TreeMap; <code>@Transactional</code> propagation modes; JDK vs CGLIB proxies).</li><li><strong>Performance characteristics</strong> of Java&#39;s actual collections and concurrency primitives.</li><li><strong>Code examples</strong> showing correct vs incorrect patterns — concrete, not abstract.</li><li><strong>Interview-style questions with answers</strong> — what gets asked, how to answer.</li><li><strong>Quick recall Q&amp;As</strong> — 5-7 pairs, each answer 1-2 lines.</li></ul><h2 id="what-gets-cut-or-never-written" tabindex="-1">What gets cut (or never written) <a class="header-anchor" href="#what-gets-cut-or-never-written" aria-label="Permalink to &quot;What gets cut (or never written)&quot;">​</a></h2><ul><li>Comparative analyses of alternatives Java doesn&#39;t use (open addressing, Python dict internals, .NET Dictionary, Ruby Hash internals).</li><li>&quot;When you&#39;d pick X vs Y&quot; for decisions a Java application developer never makes (you don&#39;t choose your hashmap&#39;s collision strategy).</li><li>Specialised algorithms irrelevant to Java interviews (cuckoo hashing, Robin Hood, hopscotch, etc.).</li><li>Historical context that doesn&#39;t explain a current gotcha or a question an interviewer would ask. Cut &quot;it used to work differently before Java X&quot; with no current bearing.</li><li>Academic depth on JDK design choices where knowing the outcome is enough.</li><li>Any section the reader must read entirely before realising it&#39;s skippable.</li></ul><p><strong>Calibration example — content cut from <code>Hashing.md</code>:</strong> a ~100-line walkthrough of open addressing (separate chaining alternative) including linear probing, tombstones, load factor tables comparing Java vs Python dict. Java uses separate chaining; the developer never picks. The only salvage was one sentence — &quot;Java HashMap uses separate chaining&quot; — folded into the existing collision section. Everything else gone.</p><p>If you&#39;re tempted to write something that feels like that — survey of alternatives, implementation choices the developer doesn&#39;t make, detail that exists for completeness — don&#39;t.</p><hr><h2 id="doc-structure" tabindex="-1">Doc structure <a class="header-anchor" href="#doc-structure" aria-label="Permalink to &quot;Doc structure&quot;">​</a></h2><h3 id="theory-docs-most-foundation-concurrency-spring-content-docs" tabindex="-1">Theory docs (most foundation/concurrency/spring content docs) <a class="header-anchor" href="#theory-docs-most-foundation-concurrency-spring-content-docs" aria-label="Permalink to &quot;Theory docs (most foundation/concurrency/spring content docs)&quot;">​</a></h3><p>Standard shape:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Title</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## How it works  (or domain-specific section names — internals, mechanism, contract)</span></span>
<span class="line"><span>## Gotchas / Pitfalls / Trick questions</span></span>
<span class="line"><span>## Comparisons within Java  (where applicable: types, modes, alternatives Java itself provides)</span></span>
<span class="line"><span>## Performance characteristics  (where applicable)</span></span>
<span class="line"><span>## Quick recall</span></span></code></pre></div><ul><li>Start direct. No intro fluff about &quot;what hashing is&quot; if the reader is already past that.</li><li>Each section short and dense. Two short paragraphs beats one long one.</li><li>Code blocks fenced <code>\\</code>\`\`java\` — concrete patterns, not abstract examples.</li><li>End with <code>## Quick recall</code> — 5-7 Q&amp;A pairs, each answer 1-2 lines max.</li></ul><h3 id="exercise-guides-part-1b-coding-fluency-style" tabindex="-1">Exercise guides (Part 1b Coding Fluency style) <a class="header-anchor" href="#exercise-guides-part-1b-coding-fluency-style" aria-label="Permalink to &quot;Exercise guides (Part 1b Coding Fluency style)&quot;">​</a></h3><p>Standard shape:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Title</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Domain model  (the types/setup the exercise builds on)</span></span>
<span class="line"><span>## Exercise 1 — &lt;task name&gt;</span></span>
<span class="line"><span>   Task → Gotchas → Acceptance criteria</span></span>
<span class="line"><span>## Exercise 2 — ...</span></span>
<span class="line"><span>## Trick questions / gotchas  (cross-exercise)</span></span>
<span class="line"><span>## Quick recall</span></span></code></pre></div><p>The keep/cut test for exercise docs becomes: &quot;does this help practice the skill or warn about a coding gotcha?&quot; Academic theory beyond what&#39;s needed to complete the exercise gets cut.</p><hr><h2 id="format-rules" tabindex="-1">Format rules <a class="header-anchor" href="#format-rules" aria-label="Permalink to &quot;Format rules&quot;">​</a></h2><ul><li><strong>Pure GitHub-flavored Markdown.</strong> No HTML tags — they don&#39;t survive Notion paste.</li><li><strong>H1 once</strong> (title). H2 for main sections, H3 for subsections only when needed.</li><li><strong>Tables</strong> with <code>|</code> pipes for multi-column reference content.</li><li><strong>Code blocks</strong> fenced with \`\`\`java (or other language).</li><li><strong>Lists</strong> with <code>-</code> for bullets, <code>1.</code> for ordered.</li><li><strong>Never <code>## Done when</code> (checklist style).</strong> Use <code>## Quick recall</code> (Q&amp;A style) instead. Checklists are textbook-style; Q&amp;As are interview-style.</li><li><strong>No emojis</strong> except the tier/tag symbols used in Part-row tables (<code>🔴 🟠 🟡 🟢 💼 🔐 🎯 📖 💻</code>).</li></ul><hr><h2 id="when-applying-to-an-existing-draft" tabindex="-1">When applying to an existing draft <a class="header-anchor" href="#when-applying-to-an-existing-draft" aria-label="Permalink to &quot;When applying to an existing draft&quot;">​</a></h2><p>If a section already exists but feels like the cut list — academic survey, alternative explanation, historical trivia, comparative content the reader will skip — cut it before publishing. Don&#39;t rationalise: if you have to argue for keeping it, it doesn&#39;t belong.</p><p>For sweeping older bloated docs, use the sibling <code>DocCleanupPrompt.md</code> — that&#39;s the subagent-ready version of the cut criteria.</p>`,36)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
